// Plattform-HTTPS-Adresse eintragen. Der SFTP-Pfad ist in QNAP File Station Buchhaltung/Kassendoku.
const platformUrl = 'https://DEINE-ZEITERFASSUNG-DOMAIN';
const qnapBasePath = '/share/Buchhaltung/Kassendoku';
return [{json: {platform_url: platformUrl.replace(/\/$/, ''), qnap_base_path: qnapBasePath.replace(/\/+$/, '')}}];

const config = $('Konfiguration').first().json;
const docs = $json.documents;
if (!Array.isArray(docs)) throw new Error('Keine gültige Dokumentenliste von der Plattform erhalten.');
return docs.map(doc => {
  if (!/^(handover|day)-[1-9]\d*$/.test(doc.document_key || '')) throw new Error('Ungültiger Dokumentenschlüssel.');
  if (!/^\d{4}\/\d{2}\/\d{4}\.\d{2}\.\d{2}-(Schicht(?:-\d{2,})?|Tag)\.pdf$/.test(doc.relative_path || '')) throw new Error('Ungültiger Archivpfad.');
  const [kind, id] = doc.document_key.split('-');
  if (doc.download_path !== `/api/integrations/cash-documents/${kind}/${id}/pdf` || doc.ack_path !== `/api/integrations/cash-documents/${kind}/${id}/ack`) throw new Error('Ungültiger Dokumenten-Endpunkt.');
  if (!config.qnap_base_path.startsWith('/') || config.qnap_base_path.split('/').includes('..')) throw new Error('Vollständigen QNAP-Basispfad konfigurieren.');
  return {json: {...doc, ...config, qnap_path: `${config.qnap_base_path}/${doc.relative_path}`}, pairedItem: {item: 0}};
});

const doc = $('Dokumente aufteilen').item.json;
if (!$binary?.data) throw new Error('PDF-Download fehlt im Binärfeld data.');
return {json: {...doc}, binary: {data: $binary.data}};
